<?php
declare(strict_types=1);
require_once __DIR__ . '/src/Allocator.php';
$dbPath = __DIR__ . '/data/smart64.sqlite';
$journalPath = getenv('SMART64_JOURNAL_PATH') ?: dirname(__DIR__) . '/smart64-journal/allocations.jsonl';
$allocator = new Allocator($dbPath, $journalPath);
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
$message = ''; $error = ''; $result = null; $report = null;
function h(string|int|float|null $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function postInt(string $key, int $default = 0): int { $v = filter_input(INPUT_POST, $key, FILTER_VALIDATE_INT); return $v === false || $v === null ? $default : $v; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) throw new RuntimeException('Security token expired. Reload the page and try again.');
        $action = (string)($_POST['action'] ?? '');
        if ($action === 'register') { $e = postInt('engine'); $allocator->registerEngine($e); $message = "Engine {$e} is registered (or was already registered)."; }
        elseif ($action === 'generate') { $result = $allocator->allocate(postInt('engine'), postInt('class', 1), postInt('role', 1)); $message = 'One SMART v1.41 ID was allocated and persisted.'; }
        elseif ($action === 'benchmark') { $report = $allocator->benchmark(postInt('engines', 1), postInt('count', 100), postInt('class', 1), postInt('role', 1)); $_SESSION['last_report'] = $report; $message = 'Benchmark completed. Results include SQLite persistence.'; }
        elseif ($action === 'csv') { $rows = $allocator->recent(200); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="smart64-allocations.csv"'); $out = fopen('php://output', 'w'); fputcsv($out, ['engine','local','class','class_name','role','id_decimal','id_hex','created_at']); foreach ($rows as $r) fputcsv($out, [$r['engine_no'],$r['local_id'],$r['class_id'],$r['class_name'],$r['role_id'],$r['id_decimal'],$r['id_hex'],$r['created_at']]); fclose($out); exit; }
        elseif ($action === 'report') { $r = $_SESSION['last_report'] ?? null; if (!$r) throw new RuntimeException('Run a benchmark first.'); header('Content-Type: application/json; charset=utf-8'); header('Content-Disposition: attachment; filename="smart64-benchmark-report.json"'); echo json_encode(['specification'=>'SMART 64-Bit ID v1.41','generated_at'=>gmdate('c'),'benchmark'=>$r], JSON_PRETTY_PRINT | JSON_THROW_ON_ERROR); exit; }
        else throw new RuntimeException('Unknown action.');
    } catch (Throwable $e) { $error = $e->getMessage(); }
}
$engines = $allocator->listEngines(); $recent = $allocator->recent(30); $lastReport = $_SESSION['last_report'] ?? null;
$classes = [1=>'Human',2=>'Other Living Being',3=>'IoT / Device',4=>'AI',5=>'Organization',6=>'Artifact / Object',7=>'Android / Humanoid Artificial Entity',8=>'Natural / Celestial Object'];
?>
