:root{color-scheme:light;--ink:#172033;--muted:#5d687b;--line:#dce2eb;--blue:#2357c6;--pale:#f4f7fb}*{box-sizing:border-box}body{margin:0;background:var(--pale);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}header{background:#101b31;color:white;padding:30px 18px}header .wrap,main{max-width:1100px;margin:auto}header p{color:#cbd6eb;margin-bottom:0}.wrap{padding-left:16px;padding-right:16px}main{padding:24px 16px 50px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px;box-shadow:0 3px 14px #1a2b4d0a}h1{margin:0;font-size:clamp(1.5rem,4vw,2.3rem)}h2{font-size:1.2rem;margin-top:0}label{display:block;font-weight:650;margin:12px 0 5px}input,select{font:inherit;width:100%;padding:10px;border:1px solid #b9c4d6;border-radius:8px;background:white}button{font:inherit;font-weight:700;background:var(--blue);color:white;border:0;border-radius:8px;padding:10px 14px;margin-top:14px;cursor:pointer}button.secondary{background:#e9eef8;color:#172033}.note{color:var(--muted);font-size:.92rem}.msg,.err{padding:12px 14px;border-radius:8px;margin-bottom:14px}.msg{background:#e5f5ea;color:#16532a}.err{background:#fff0ef;color:#8c241c}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f8faff}footer{color:var(--muted);font-size:.88rem;padding-top:12px}.pill{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:2px 9px;font-size:.8rem}
