<?php if ($message): ?><div class="msg"><?=h($message)?></div><?php endif; ?><?php if ($error): ?><div class="err"><strong>Request not completed:</strong> <?=h($error)?></div><?php endif; ?>
<div class="card"><strong>Prototype scope:</strong> This demo uses one authoritative local SQLite database file. It is not a distributed allocator and cannot by itself guarantee non-reuse after restoring an older database backup or across independent database copies. Protect the database and backups operationally before production use.</div>
<div class="grid"><section class="card"><h2>1. Register an engine</h2><p class="note">Engine is a 21-bit namespace number. Re-registering an existing number does not reset its counter.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="register"><label for="engine">Engine number (0–2,097,151)</label><input id="engine" name="engine" type="number" min="0" max="2097151" value="0" required><button type="submit">Register engine</button></form></section>
<section class="card"><h2>2. Generate one ID</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="generate"><label for="gengine">Registered engine</label><select id="gengine" name="engine" required><?php foreach($engines as $e): ?><option value="<?=h($e['engine_no'])?>">Engine <?=h($e['engine_no'])?> · next Local <?=h($e['next_local'])?></option><?php endforeach; ?></select><label for="gclass">Class</label><select id="gclass" name="class"><?php foreach($classes as $k=>$v): ?><option value="<?=$k?>"><?=$k?> — <?=h($v)?></option><?php endforeach; ?></select><label for="grole">Role</label><select id="grole" name="role"><option value="1">1 — Self-representing</option><option value="0">0 — Dependent</option></select><button type="submit">Allocate ID</button></form></section>
<section class="card"><h2>3. Multi-engine benchmark</h2><p class="note">Creates/registers Engine 0 onward, then allocates the selected count per engine. Existing counters are continued, not reset. Web safety cap: 100 engines × 1,000 IDs.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="benchmark"><label for="engines">Number of engines (1–100)</label><input id="engines" name="engines" type="number" min="1" max="100" value="10" required><label for="count">IDs per engine (1–1,000)</label><input id="count" name="count" type="number" min="1" max="1000" value="100" required><label for="bclass">Class</label><select id="bclass" name="class"><?php foreach($classes as $k=>$v): ?><option value="<?=$k?>"><?=$k?> — <?=h($v)?></option><?php endforeach; ?></select><label for="brole">Role</label><select id="brole" name="role"><option value="1">1 — Self-representing</option><option value="0">0 — Dependent</option></select><button type="submit">Run benchmark</button></form></section></div>
<?php if ($result): ?><section class="card"><h2>Allocated identifier</h2><p>Unsigned decimal: <strong class="mono"><?=h($result['id_decimal'])?></strong></p><p>Canonical big-endian bytes (hex): <strong class="mono"><?=h($result['id_hex'])?></strong></p><p>Engine <?=h($result['engine'])?> · Local <?=h($result['local'])?> · Class <?=h($result['class'])?> (<?=h($result['class_name'])?>) · Role <?=h($result['role'])?> · Version <?=h($result['version'])?> · Revision <?=h($result['revision'])?> · Reserved <?=h($result['reserved'])?></p></section><?php endif; ?>
<?php if ($lastReport): ?><section class="card"><h2>Latest benchmark report</h2><div class="grid"><div><div class="note">IDs generated</div><strong><?=h($lastReport['generated'])?></strong></div><div><div class="note">Elapsed seconds</div><strong><?=h(number_format($lastReport['elapsed_seconds'],6))?></strong></div><div><div class="note">IDs per second</div><strong><?=h(number_format($lastReport['ids_per_second'],2))?></strong></div><div><div class="note">Measured workload</div><strong><?=h($lastReport['mode'])?></strong></div></div><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="report"><button type="submit">Download JSON report</button></form></section><?php endif; ?>
<section class="card"><h2>Registered engines</h2><?php if (!$engines): ?><p class="note">No engines registered yet. Register one above to start.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Engine</th><th>Next Local</th><th>State</th><th>Created</th></tr></thead><tbody><?php foreach($engines as $e): ?><tr><td><?=h($e['engine_no'])?></td><td><?=h($e['next_local'])?></td><td><span class="pill">registered</span></td><td><?=h($e['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card"><h2>Recent allocations</h2><p class="note">The decimal ID is rendered as text to avoid JavaScript or signed-integer precision loss.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="csv"><button class="secondary" type="submit">Download recent allocations (CSV, up to 200)</button></form><div class="table-wrap"><table><thead><tr><th>Engine</th><th>Local</th><th>Class</th><th>Role</th><th>Unsigned decimal ID</th><th>Binary hex</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?=h($r['engine_no'])?></td><td><?=h($r['local_id'])?></td><td><?=h($r['class_id'])?> — <?=h($r['class_name'])?></td><td><?=h($r['role_id'])?></td><td class="mono"><?=h($r['id_decimal'])?></td><td class="mono"><?=h($r['id_hex'])?></td></tr><?php endforeach; ?><?php if (!$recent): ?><tr><td colspan="6">No allocations yet.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card"><h2>Implemented v1.41 checks</h2><ul><li>Exact bit offsets from the v1.41 README.</li><li>Reserved bits forced to zero at generation and validated at decode.</li><li>Class 0 rejected; Local 0 accepted.</li><li>Version 0 / Revision 1 enforced; unknown profiles rejected.</li><li>Canonical 8-byte big-endian BLOB and unsigned decimal text.</li><li>SQLite <code>BEGIN IMMEDIATE</code> transaction, uniqueness constraints and monotonic Local counter.</li></ul><p class="note">This initial prototype does not implement cross-host fencing, distributed ownership transfer, or rollback-proof allocation history. Do not describe it as production-grade distributed conformance.</p></section>
<footer>SMART 64-Bit ID v1.41 · Prototype controller · Use only in a trusted test environment until deployment hardening and recovery procedures are reviewed.</footer></main></body></html>
